/// <summary>
///    The <c>METSalesOrderWaveGeneratedBusinessEvent</c> class extends <c>BusinessEventsBase</c> to provide customer status change business event.
/// </summary>
[BusinessEvents(classStr(METSalesOrderWaveGeneratedBusinessEventContract),
    "@MET:SalesOrderWaveBusinessEventName",
    "@MET:SalesOrderWaveBusinessEventDesc",
    ModuleAxapta::Customer)]
class METSalesOrderWaveGeneratedBusinessEvent extends BusinessEventsBase
{
    private METWaveId  waveId;

}

Method.Source:
/// <summary>
/// Constructs a new METSalesOrderWaveGeneratedBusinessEvent business event.
/// </summary>
/// <param name = "_waveId">WaveId</param>
/// <returns>A new <c>METSalesOrderWaveGeneratedBusinessEvent</c> business event.</returns>
public static METSalesOrderWaveGeneratedBusinessEvent newFromSalesWave(METWaveId _waveId)
{
    METSalesOrderWaveGeneratedBusinessEvent event = new METSalesOrderWaveGeneratedBusinessEvent();
    event.parmWaveId(_waveId);

    return event;
}

/// <summary>
/// Get or set wave id
/// </summary>
/// <param name = "_waveId">Wave Id</param>
/// <returns>METWaveId</returns>
public METWaveId parmWaveId(METWaveId _waveId = waveId)
{
    waveId = _waveId;

    return waveId;
}

/// <summary>
/// Overrides to provide wave id information when sales extraction is performed.
/// </summary>
/// <returns>The <c>METSalesOrderWaveGeneratedBusinessEventContract</c> of the event.</returns>
public BusinessEventsContract buildContract()
{
    return METSalesOrderWaveGeneratedBusinessEventContract::newFromSalesOrderExtractionDetails(waveId);
}

/// <summary>
/// Creates new object
/// </summary>
private void new()
{
}
